import{_ as o,o as e,c as r,a3 as d}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Cores no resultado do cumprimento de mandados","description":"","frontmatter":{"title":"Cores no resultado do cumprimento de mandados","id":"eproc-cores-resultado-mandado","plataforma":"eproc","grupo":"Mandados","plano":"free","desde":"1.12.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-cores-resultado-mandado"}]]},"headers":[],"relativePath":"funcionalidades/eproc-cores-resultado-mandado.md","filePath":"funcionalidades/eproc-cores-resultado-mandado.md"}'),s={name:"funcionalidades/eproc-cores-resultado-mandado.md"};function t(n,a,i,c,u,l){return e(),r("div",null,a[0]||(a[0]=[d('<h1 id="cores-no-resultado-do-cumprimento-de-mandados" tabindex="-1">Cores no resultado do cumprimento de mandados <a class="header-anchor" href="#cores-no-resultado-do-cumprimento-de-mandados" aria-label="Permalink to &quot;Cores no resultado do cumprimento de mandados&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na certificação de mandados, as opções &quot;Cumprido&quot; e &quot;Cumprido Negativo&quot; do campo &quot;Resultado&quot; são fáceis de confundir, principalmente ao lançar vários mandados seguidos. Com este recurso, o campo fica verde quando o resultado é &quot;Cumprido&quot; e vermelho quando é &quot;Cumprido Negativo&quot;.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, no perfil da Central de Mandados, na tela do mandado, no quadro &quot;Certificação&quot;.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra o mandado e vá até o quadro &quot;Certificação&quot;.</li><li>Escolha o resultado no campo &quot;Resultado&quot;.</li><li>Confira a cor antes de salvar: verde para &quot;Cumprido&quot;, vermelho para &quot;Cumprido Negativo&quot;.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><p>As duas opções também aparecem coloridas na lista aberta, exceto no macOS, onde a lista do sistema não aceita cores. A extensão só muda a aparência do campo: o resultado lançado no eproc é o mesmo.</p>',11)]))}const q=o(s,[["render",t]]);export{m as __pageData,q as default};
